<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <div class="hero">
        <span class="eyebrow">Developer basics</span>
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose every answer that applies. Each question accepts more than one selection.</p>
      </div>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset>
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text">Select all languages used to write software, not markup or styling languages.</p>
            <div class="choices">
              <label>
                <input type="checkbox" name="programming-languages" value="python">
                <span>Python</span>
              </label>
              <label>
                <input type="checkbox" name="programming-languages" value="javascript">
                <span>JavaScript</span>
              </label>
              <label>
                <input type="checkbox" name="programming-languages" value="html">
                <span>HTML</span>
              </label>
              <label>
                <input type="checkbox" name="programming-languages" value="css">
                <span>CSS</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages commonly run in web browsers?</legend>
            <div class="choices">
              <label>
                <input type="checkbox" name="browser-languages" value="javascript">
                <span>JavaScript</span>
              </label>
              <label>
                <input type="checkbox" name="browser-languages" value="webassembly">
                <span>WebAssembly</span>
              </label>
              <label>
                <input type="checkbox" name="browser-languages" value="sql">
                <span>SQL</span>
              </label>
              <label>
                <input type="checkbox" name="browser-languages" value="bash">
                <span>Bash</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which languages are statically typed by default?</legend>
            <div class="choices">
              <label>
                <input type="checkbox" name="static-languages" value="java">
                <span>Java</span>
              </label>
              <label>
                <input type="checkbox" name="static-languages" value="go">
                <span>Go</span>
              </label>
              <label>
                <input type="checkbox" name="static-languages" value="ruby">
                <span>Ruby</span>
              </label>
              <label>
                <input type="checkbox" name="static-languages" value="python">
                <span>Python</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p id="result" class="result" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#quiz-form");
    const result = document.querySelector("#result");

    form.addEventListener("submit", (event) => {
