      const selectedCount = form.querySelectorAll("input[type='checkbox']:checked").length;
      result.textContent = `Thanks! You selected ${selectedCount} answer${selectedCount === 1 ? "" : "s"}.`;
      result.classList.add("is-visible");
    });
  </script>
</body>
</html>
